public sealed record Error(string Code, string Message, int Status);
public sealed record Result<T>(T? Value, Error? Error)
{
    public bool IsSuccess => Error is null;
    public static Result<T> Ok(T value) => new(value, null);
    public static Result<T> Fail(Error error) => new(default, error);
}

// jedno miejsce mapowania na HTTP
public static IResult ToHttp<T>(this Result<T> r) => r.IsSuccess
    ? TypedResults.Ok(r.Value)
    : TypedResults.Problem(title: r.Error!.Code, detail: r.Error.Message,
                           statusCode: r.Error.Status);

public async Task<Result<Unit>> Handle(CancelOrder cmd, CancellationToken ct)
{
    var order = await orders.GetWithLinesAsync(new OrderId(cmd.OrderId), ct);   // Repository
    if (order is null)
        return Result<Unit>.Fail(new("order.not_found", "Brak zamówienia", 404)); // Result

    var cancelled = order.Cancel();                                              // reguła w encji
    if (!cancelled.IsSuccess) return Result<Unit>.Fail(cancelled.Error!);

    await uow.SaveChangesAsync(ct);                                              // Unit of Work
    return Result<Unit>.Ok(Unit.Value);
}

public readonly record struct OrderId(Guid Value) { public static OrderId New() => new(Guid.CreateVersion7()); }
public enum OrderStatus { Placed, Cancelled }

public sealed class Order
{
    private readonly List<OrderLine> _lines = [];
    private Order() { }                                   // dla EF Core
    public OrderId Id { get; private set; }
    public Guid CustomerId { get; private set; }
    public OrderStatus Status { get; private set; }
    public IReadOnlyList<OrderLine> Lines => _lines;

    public static Result<Order> Place(Guid customerId, IEnumerable<OrderLine> lines)
    {
        var order = new Order { Id = OrderId.New(), CustomerId = customerId, Status = OrderStatus.Placed };
        order._lines.AddRange(lines);
        if (order._lines.Count == 0) return Result<Order>.Fail(Errors.EmptyOrder);
        if (order._lines.Any(l => l.Quantity <= 0)) return Result<Order>.Fail(Errors.BadQuantity);
        return Result<Order>.Ok(order);
    }

    public Result<Order> Cancel()
    {
        if (Status == OrderStatus.Cancelled) return Result<Order>.Fail(Errors.AlreadyCancelled);
        Status = OrderStatus.Cancelled;
        return Result<Order>.Ok(this);
    }
}

public interface IOrderRepository { Task<Order?> GetAsync(OrderId id, CancellationToken ct); void Add(Order order); }
public interface IUnitOfWork { Task<int> SaveChangesAsync(CancellationToken ct = default); }

public sealed record PlaceOrderCommand(Guid CustomerId, IReadOnlyList<PlaceOrderLine> Lines);
public sealed record PlaceOrderLine(string Sku, int Quantity, decimal UnitPrice);

public sealed class PlaceOrderHandler(IOrderRepository orders, IUnitOfWork uow)
{
    public async Task<Result<Guid>> Handle(PlaceOrderCommand cmd, CancellationToken ct)
    {
        var lines = cmd.Lines.Select(l => new OrderLine(l.Sku, l.Quantity, l.UnitPrice));
        var placed = Order.Place(cmd.CustomerId, lines);
        if (!placed.IsSuccess) return Result<Guid>.Fail(placed.Error!);

        orders.Add(placed.Value!);
        await uow.SaveChangesAsync(ct);
        return Result<Guid>.Ok(placed.Value!.Id.Value);
    }
}

public sealed class ShopDb(DbContextOptions<ShopDb> o) : DbContext(o), IUnitOfWork
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder b) => b.ApplyConfigurationsFromAssembly(typeof(ShopDb).Assembly);
}

internal sealed class OrderConfiguration : IEntityTypeConfiguration<Order>
{
    public void Configure(EntityTypeBuilder<Order> b)
    {
        b.HasKey(o => o.Id);
        b.Property(o => o.Id).HasConversion(id => id.Value, v => new OrderId(v));
        b.OwnsMany(o => o.Lines, l => { l.WithOwner().HasForeignKey("OrderId"); l.Property(x => x.UnitPrice).HasPrecision(18, 2); });
    }
}

